function normText(t) {
  return String(t).replace(/\r/g, '').replace(/[*`]+/g, '').replace(/^[ \t]*(>[ \t]?)+/gm, '')
    .replace(/[ \t  -​　]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{2,}/g, '\n').trim();
}

