  RX(EB + "you\\s+are\\s+no\\s+longer\\s+(?:(?:an?|the|my|your)\\s+)?(?:[\\p{L}-]+\\s+){0,2}?" + AI_NOUN + EE),
  RX(EB + "(?:you\\s+are|you're)\\s+now\\s+[^.!?\\n]{0,40}?" + RULE_WORDS),
  RX("\\b[Yy]ou\\s+are\\s+now\\s+[A-Z][\\w-]*(?:\\s*\\d[\\d.]*)?\\s*(?:[,.]\\s*)?(?:an?\\s+(?:AI|ai|bot|assistant|model)\\b|without\\b|with\\s+no\\b|and\\s+you\\b)", 'u'),
  RX(EB + "(?:you\\s+are|you're)\\s+now\\s+(?:in|entering)\\s+(?:\\p{L}+\\s+){0,2}?(?:developer|admin|god|debug|jailbreak|dan|unrestricted|sudo|root|maintenance)\\s+mode" + EE),
  RX(EB + "(?:you\\s+are|you're)\\s+now\\s+(?:acting|playing|operating|working)\\s+as" + EE),
  RX(EB + "(?:pretend|imagine)\\s+(?:that\\s+)?(?:you\\s+are|you're|to\\s+be)\\s+[^.!?\\n]{0,40}?(?:" + AI_NOUN + "|" + RULE_WORDS + ")" + EE),
  RX(EB + "(?:roleplay|role-play|role\\s+play)\\s+as\\s+[^.!?\\n]{0,40}?(?:" + AI_NOUN + "|" + RULE_WORDS + ")" + EE),
  RX(EB + "(?:act|behave|respond|answer)\\s+(?:as|like)\\s+(?:an?\\s+|the\\s+)?(?:(?:unrestricted|uncensored|unfiltered|different|new|other|evil|jailbroken|free)\\s+)(?:" + AI_NOUN + ")" + EE),
  RX(EB + "(?:act|behave)\\s+as\\s+(?:an?\\s+|the\\s+)?" + AI_NOUN + "\\s+(?:with\\s+no|without)\\s+(?:rules|restrictions|limits|filters)"),
  RX(EB + "your\\s+new\\s+(?:role|job|task|purpose|instructions?)\\s+(?:is|are|:)"),
  RX(EB + "(?:here\\s+are|these\\s+are)\\s+(?:your|the)\\s+new\\s+instructions?"),
  RX(EB + "from\\s+now\\s+on\\s*,?\\s+(?:you\\s+are|you're|you\\s+will|you'll|you\\s+must|you\\s+should)\\s+(?:(?:an?|the)\\s+)?(?:[\\p{L}-]+\\s+){0,3}?(?:" + AI_NOUN + "|only\\s+(?:answer|respond|reply|output)|answer|respond|reply|output|ignore|mark|set|classify)" + EE),
  RX(EB + "(?:du\\s+bist\\s+(?:jetzt|nun|ab\\s+jetzt)|ab\\s+jetzt\\s+bist\\s+du|tu\\s+es\\s+(?:maintenant|désormais)|désormais\\s+tu\\s+es|vous\\s+êtes\\s+(?:maintenant|désormais)|ahora\\s+eres|ahora\\s+es\\s+usted|a\\s+partir\\s+de\\s+ahora\\s+eres|ora\\s+sei|adesso\\s+sei|d'ora\\s+in\\s+poi\\s+sei|agora\\s+(?:você\\s+é|tu\\s+és|és)|jij\\s+bent\\s+nu|je\\s+bent\\s+nu|teraz\\s+jesteś|sada\\s+si|теперь\\s+ты)\\s+(?:[^.!?\\n]{0,30}?\\s)?" + AI_NOUN + EE),
];

// tags, headings and comments
const TAGS = [
  /<<\/?SYS>>/i, /<\|(?:system|user|assistant|im_start|im_end)\|>/i, /\[\/?(?:SYSTEM|INST)\]/i,
  /\{\{\s*system\s*\}\}/i, /<\/?\s*(?:system|assistant|instructions?)\s*>/i, /\[system\]\(#/i,
  RX('#{1,6} ?(?:new\\s+)?(?:system\\s+)?instructions?' + EE),
  RX('(?:^|\\n)#{1,6} ?response\\s*:'),
  RX('<!--[^>]{0,300}?' + EB + '(?:assistant|ai|a\\.i\\.|bot|llm|claude|gpt|chatgpt|model|instructions?)' + EE + '[^>]{0,300}?-->'),
];

// attack modes switched on
const MODE = '(?:developer|admin|administrator|debug|god|jailbreak|dan|unrestricted|sudo|root|maintenance)\\s+mode';
const MODES = [
  RX(EB + MODE + '\\s*:'),
  RX('(?:^|\\n|[.!?;]\\s)\\s*(?:please\\s+)?(?:enable|activate|enter|switch\\s+(?:in)?to|turn\\s+on|go\\s+into)\\s+(?:the\\s+|your\\s+)?' + MODE + EE),
  RX(EB + MODE + '\\s+(?:is\\s+)?(?:now\\s+)?(?:on|enabled|activated|active)\\s*(?:[.!]|$|\\n)'),
  RX(EB + '(?:god|jailbreak|dan|unrestricted|sudo)\\s+mode' + EE),
  RX('(?:modo\\s+(?:de\\s+)?desarrollador|modalità\\s+sviluppatore|mode\\s+développeur|entwicklermodus|modo\\s+(?:de\\s+)?desenvolvedor|ontwikkelaarsmodus|tryb\\s+dewelopera|режим\\s+разработчика)(?:\\s*:|\\s+(?:activado|activada|attivata|attivo|activé|aktiviert|ativado|geactiveerd|aktywny|включ\\S*)\\s*(?:[.!:]|$|\\n))'),
  RX('(?:^|\\n|[.!?;]\\s)\\s*(?:aktiviere|activa|attiva|active|activez|ative|włącz)\\s+(?:den\\s+|el\\s+|la\\s+|le\\s+|o\\s+)?(?:entwicklermodus|modo\\s+(?:de\\s+)?desarrollador|modalità\\s+sviluppatore|mode\\s+développeur|modo\\s+(?:de\\s+)?desenvolvedor|tryb\\s+dewelopera)'),
];

// field orders: an order verb + a schema field + a value that field allows
const FIELD_TR = {
  priority: ['priorität', 'priorite', 'priorité', 'prioridad', 'priorità', 'prioridade', 'prioriteit', 'priorytet',
    'prioritet', 'приоритет'],
  urgency: ['dringlichkeit', 'urgence', 'urgencia', 'urgenza', 'urgência'],
  category: ['kategorie', 'catégorie', 'categoría', 'categoria', 'categorie', 'kategoria', 'категорию', 'категория'],
};
const VALUE_TR = ['niedrig', 'hoch', 'dringend', 'basse', 'bas', 'haute', 'élevée', 'urgente', 'baja', 'alta', 'bassa',
  'baixa', 'laag', 'hoog', 'niski', 'wysoki', 'nizak', 'visok', 'низкий', 'высокий', 'срочный', 'normale', 'normal'];
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function fieldRegexes(schema) {
  const props = (schema && schema.properties) || {};
  const out = [];
  for (const [k, s] of Object.entries(props)) {
    const names = [esc(k)];
    if (k.includes('_')) names.push(esc(k).replace(/_/g, '[\\s_-]+'));
    for (const tr of FIELD_TR[k] || []) names.push(tr);
    const types = Array.isArray(s.type) ? s.type : [s.type];
    const values = [];
    if (Array.isArray(s.enum)) values.push(...s.enum.filter((x) => typeof x === 'string').map(esc));
    if (types.includes('boolean')) values.push('true', 'false', 'yes', 'no', 'wahr', 'falsch', 'vrai', 'faux', 'verdadero', 'falso', 'vero', 'verdadeiro');
    if (types.includes('number') || types.includes('integer')) values.push('-?\\d+(?:[.,]\\d+)?', 'zero', 'null', 'none');
    if (FIELD_TR[k]) values.push(...VALUE_TR);
    if (!values.length) continue;
    const F = '(?:' + names.join('|') + ')';
    const V = '(?:' + values.join('|') + ')';
    out.push(RX(EB + '(?:' + alt(IMP) + ')' + EE + '[^.!?\\n]{0,40}?' + EB + F + EE + '[^.!?\\n]{0,25}?' + EB + V + EE));
    out.push(RX(EB + '(?:' + alt(IMP) + ')' + EE + '[^.!?\\n]{0,40}?' + EB + V + EE + '\\s+' + F + EE));
    out.push(RX(EB + F + EE + '\\s*(?:=|is|should\\s+be|must\\s+be|to|as|of|:)\\s*"?' + V + EE));
  }
  return out;
}

function keyRegex(schema) {
  const keys = Object.keys((schema && schema.properties) || {}).map(esc);
  return keys.length ? RX('"(?:' + keys.join('|') + ')"\\s*:') : null;
}

const FIXED = [
  RX(EB + '(?:return|respond|reply|answer|output|use|give|print|write|send\\s+back|devuelve|devuelva|responde|responda|retorne|retorna|restituisci|rispondi|renvoie|renvoyez|réponds|répondez|gib|antworte|verwende|usa|utilise)' + EE + '[\\s\\S]{0,80}?\\{\\s*"[^"\\n]{1,40}"\\s*:'),
  RX(EB + '(?:correct|expected|right|desired|required|final)\\s+(?:output|answer|json|response|result)' + EE + '\\s*(?:is|:|=)?\\s*\\{'),
  RX(EB + '(?:your|the)\\s+(?:answer|response|output|reply|json)\\s+(?:must|should|has\\s+to)\\s+be\\s+(?:exactly\\s+)?(?:this\\s*:?\\s*)?\\{'),
  RX(EB + '(?:return|respond|reply|answer|output)' + EE + '[^.!?\\n]{0,40}?' + EB + '(?:exactly|only|this|the\\s+following)' + EE + '[\\s\\S]{0,40}?\\{\\s*"'),
];

const ADDRESS = [
  RX('(?:^|\\n|[.!?;]\\s|,\\s)\\s*(?:hey|hi|hello|dear|attention|ok)?\\s*,?\\s*(?:chatgpt|chat\\s+gpt|gpt|gemini|copilot|claude|llm|ai|a\\.i\\.|bot|chatbot|assistant)\\s*[:,]'),
  RX(EB + '(?:note|message|instructions?|important(?:\\s+\\p{L}+){0,2})\\s+(?:to|for)\\s+(?:the\\s+|any\\s+)?(?:ai(?:\\s+model)?|a\\.i\\.|language\\s+model|llm|bot|chatbot|assistant|model|chatgpt|gpt|claude|gemini|copilot)' + EE),
  RX(EB + '(?:to|for|dear|hey|hi)\\s+(?:the\\s+|any\\s+)?(?:ai(?:\\s+model)?|language\\s+model|llm|chatgpt|gpt)\\s+(?:(?:reading|processing|that\\s+reads|that\\s+processes)\\s+this\\s*)?[:,]'),
];

const ROLE = '(?:system|assistant|developer|admin|administrator|operator|sys|root|override|sistema|système|systeme|systemnachricht|system-nachricht|система|システム|系统|系統)';
const ROLE_QUAL = '(?:message|prompt|override|note|notice|instructions?|alert|update|command|nachricht|mensaje|messaggio)';
const ROLE_RX = [
  RX('(?:\\[|\\(|<|\\{\\{)\\s?(' + ROLE + ')(?:\\s(' + ROLE_QUAL + '))?\\s?(?:\\]|\\)|>|\\}\\})\\s?:?([^\\n]{0,160})', 'gi'),
  RX(EB + '(' + ROLE + ')(?:\\s(' + ROLE_QUAL + '))?\\s?[:：]([^\\n]{0,160})', 'gi'),
  RX(EB + '(' + ROLE + ')(?:\\s(' + ROLE_QUAL + '))?\\s[-–—]{1,2}\\s([^\\n]{0,160})', 'gi'),
];
const RULES_OFF = RX('(?:rules|instructions|restrictions|guidelines)\\s+(?:no\\s+longer|do\\s+not|don.t)\\s+apply|' + EB + '(?:this|the)\\s+(?:ticket|claim|lead|message|e-?mail|request|case)\\s+is\\s+(?:not\\s+)?\\p{L}');

function isOrder(rest, F, KEY) {
  const r = rest.split(/(?<=[.!?])\s/)[0];
  return startsWithOrder(r) || RULES_OFF.test(r) || F.some((re, i) => i % 3 !== 2 && re.test(rest)) ||
    (KEY && KEY.test(rest)) || /\{\s*"|\b\w+\s*=\s*\S/.test(rest) || ignoreHit(rest) ||
    IDENTITY.some((re) => re.test(rest)) || RX(EB + "(?:you\\s+are\\s+now|you're\\s+now)" + EE).test(r);
}

function roleHit(t, F, KEY) {
  for (const re of ROLE_RX) {
    re.lastIndex = 0;
    let m;
    while ((m = re.exec(t)) !== null) {
      const role = m[1], qual = (m[2] || '').toLowerCase(), rest = m[3] || '';
      const before = t.slice(Math.max(0, m.index - 2), m.index);
      const start = m.index === 0 || /[\n.!?;(\[{<-]\s?$|^\s?$/.test(before) || /^[\n]/.test(before.slice(-1));
      const caps = role === role.toUpperCase() && /\p{Lu}/u.test(role);
      const bracket = /^[\[(<{]/.test(m[0]);
      if (start || caps || bracket) {
        if (/override|instruction|command/.test(qual) || /^override$/i.test(role) || isOrder(rest, F, KEY)) return true;
      }
      if (m.index === re.lastIndex) re.lastIndex++;
    }
  }
  return false;
}

function stringsIn(v, out) {
  out = out || [];
  if (typeof v === 'string') out.push(v);
  else if (Array.isArray(v)) v.forEach((x) => stringsIn(x, out));
  else if (isObj(v)) Object.values(v).forEach((x) => stringsIn(x, out));
  return out;
}

function injectionHits(input, schema) {
  const t = normText(stringsIn(input).join('\n'));
  const F = fieldRegexes(schema);
  const KEY = keyRegex(schema);
  const hits = [];
  if (ignoreHit(t)) hits.push('ignore earlier instructions');
  if (roleHit(t, F, KEY)) hits.push('role line');
  if (TAGS.some((re) => re.test(t))) hits.push('role tag or comment');
  if (IDENTITY.some((re) => re.test(t))) hits.push('identity switch');
  if (MODES.some((re) => re.test(t))) hits.push('mode switch');
  if (F.slice().filter((_, i) => i % 3 !== 2).some((re) => re.test(t)) || (KEY && KEY.test(t))) hits.push('field order');
  if (FIXED.some((re) => re.test(t))) hits.push('fixed answer');
  if (ADDRESS.some((re) => re.test(t))) {
    const declared = F.filter((_, i) => i % 3 === 2).some((re) => re.test(t));
    const ordered = t.split(/(?<=[.!?:,])\s|\n/).some((s) => startsWithOrder(s) && RX(EB + '(?:this|it|that|the\\s+(?:ticket|lead|claim|message|e-?mail|request))' + EE).test(s));
    if (declared || ordered) hits.push('order addressed to the AI');
  }
  const ni = RX(EB + '(?:new|updated|revised)\\s+(?:system\\s+)?instructions?\\s*[:\\-–]|(?:neue\\s+anweisungen|nouvelles\\s+instructions|nuevas\\s+instrucciones|nuove\\s+istruzioni|novas\\s+instruções|nieuwe\\s+instructies|nowe\\s+instrukcje|nove\\s+upute|новые\\s+инструкции)\\s*:').exec(t);
  if (ni) {
    const rest = t.slice(ni.index, ni.index + 120);
    const keys = Object.keys((schema && schema.properties) || {}).flatMap((k) => [esc(k), esc(k).replace(/_/g, '\\s+'), ...(FIELD_TR[k] || [])]);
    if ((keys.length && RX(EB + '(?:' + keys.join('|') + ')' + EE).test(rest)) || isOrder(t.slice(ni.index + ni[0].length, ni.index + 160), F, KEY))
      hits.push('new instructions');
  }
  return [...new Set(hits)];
}

// what the AI step returned: an answer, an API error, a transport error, or an unknown step
function classify(r) {
  r = r || {};
  if (r.http_status === undefined && r.transport_error === undefined && r.text === undefined && r.error !== undefined) {
    const m = String((r.error && r.error.message) || r.error);
    if (/not active and cannot be executed|could not be found|does not exist|not found/i.test(m))
      return { kind: 'setup', why: 'AI step not found or not published' };
    const code = Number((m.match(/\b([45]\d\d)\b/) || [])[1] || 0);
    if (code) return apiKind(code, null);
    return { kind: 'transport', why: /time ?out|ETIMEDOUT|timed out/i.test(m) ? 'timeout' : 'connection failed', retry: true, wait: 1 };
  }
  if (r.transport_error) return { kind: 'transport', why: String(r.transport_error), retry: true, wait: 1 };
  const code = Number(r.http_status || 200);
  if (code !== 200) return apiKind(code, r.retry_after);
  return { kind: 'answer', http: 200 };
}

function apiKind(code, retryAfter) {
  if (code === 429) {
    const ra = Number(retryAfter);
    return { kind: 'api', http: code, retry: true, wait: Number.isFinite(ra) && retryAfter !== null && retryAfter !== '' ? Math.min(Math.max(ra, 0), 20) : 1,
      retry_after: retryAfter === undefined ? null : retryAfter, why: 'rate limit (HTTP 429)' };
  }
  if (code >= 500 || code === 408) return { kind: 'api', http: code, retry: true, wait: 1, why: `API error (HTTP ${code})` };
  if (code === 401 || code === 403) return { kind: 'api', http: code, retry: false, why: `API key problem: the key was refused (HTTP ${code})` };
  return { kind: 'api', http: code, retry: false, why: `request refused by the API (HTTP ${code})` };
}

function evalCall(S, r, role, n) {
  const k = classify(r);
  const c = { role, n, at_ms: Date.now() - S.t0, wait_before: S.wait_used || 0, kind: k.kind, http: k.http || null,
    retry_after: k.retry_after === undefined ? null : k.retry_after, why: k.why || '' };
  S.wait_used = 0;
  if (k.kind === 'answer') {
    c.stop_reason = r.stop_reason || null;
    c.raw = r.text === undefined ? null : r.text;
    c.model = r.model || '';
    c.tokens_in = Number(r.tokens_in) || 0;
    c.tokens_out = Number(r.tokens_out) || 0;
    const errs = [];
    if (!NORMAL_STOPS.includes(c.stop_reason)) errs.push(`the answer stopped early (stop reason: ${c.stop_reason || 'none'})`);
    const p = cleanParse(c.raw);
    c.parse_ok = false; c.schema_verdict = null;
    if (!p.ok) errs.push(p.why);
    else if (!isObj(p.value)) errs.push('the answer must be one JSON object');
    else {
      const v = validate(S.schema, p.value);
      c.parse_ok = true; c.cleaned = p.cleaned; c.schema_verdict = v.length === 0;
      errs.push(...v);
      if (errs.length === 0) c.value = p.value;
    }
    c.errors = errs; c.pass = errs.length === 0;
  } else {
    c.errors = [k.why]; c.pass = false;
  }
  S.calls.push(c);
  return { c, k };
}

function fallbackNext(S) {
  return S.fallback && S.fallback.mode === 'second_step' && !S.injection ? 'second' : 'done';
}

function timeoutMs(S, waitSeconds) {
  const per = 1000 * (Number(S.options.timeout_seconds) || 60);
  const left = 170000 - (Date.now() - S.t0) - 1000 * (waitSeconds || 0);
  return Math.max(1000, Math.min(per, left));
}

function stepInput(S, role, attempt, errorList, waitSeconds) {
  return { role, attempt, ai_input: S.ai_input, error_list: errorList || null, meta: S.meta,
    options: { max_tokens: S.options.max_tokens || null, timeout_ms: timeoutMs(S, waitSeconds) } };
}

const inp = $input.first().json || {};
const t0 = Date.now();
const S = {
  call_id: 'G' + $execution.id + '-' + Math.random().toString(36).slice(2, 7), t0, started_at: new Date(t0).toISOString(),
  task: String(inp.task || ''), meta: isObj(inp.meta) ? inp.meta : {}, ai_step_id: inp.ai_step_id, ai_input: inp.ai_input,
  schema: inp.schema, fallback: isObj(inp.fallback) ? inp.fallback : { mode: 'none' }, on_approved_id: inp.on_approved_id || '',
  options: isObj(inp.options) ? inp.options : {}, calls: [], attempts: 0, second_calls: 0, errors: [], passed: null,
  passed_second: null, injection: false, injection_hits: [], setup_ok: true, setup_error: '', next: '', wait: 1, wait_used: 0,
};
function setupFail(msg) { if (S.setup_ok) { S.setup_ok = false; S.setup_error = msg; S.errors.push(msg); } }
try {
  if (!isObj(S.schema)) setupFail('setup: schema missing');
  else { const e = schemaProblems(S.schema, 'schema', true); if (e.length) setupFail('setup: schema invalid: ' + e.join('; ')); }
  const ai = S.ai_input;
  if (ai === undefined || ai === null || (isObj(ai) && stringsIn(ai).join('').trim() === '') || (typeof ai === 'string' && !ai.trim()))
    setupFail('setup: AI input missing');
  if (!S.ai_step_id || typeof S.ai_step_id !== 'string') setupFail('setup: AI step missing');
  const fb = S.fallback;
  if (!['none', 'default', 'second_step'].includes(fb.mode)) setupFail('setup: unknown fallback mode');
  else if (fb.mode === 'default' && S.setup_ok) {
    const pv = isObj(fb.value) ? validate(S.schema, fb.value) : ['the default value must be one JSON object'];
    if (pv.length) setupFail('setup: default fallback does not match the schema: ' + pv.join('; '));
  } else if (fb.mode === 'second_step' && !fb.second_step_id) setupFail('setup: second AI step missing');
  if (S.setup_ok) { S.injection_hits = injectionHits(S.ai_input, S.schema); S.injection = S.injection_hits.length > 0; }
} catch (err) { setupFail('setup: guard error: ' + err.message); }
return [{ json: S }];

// ---------- shared library (validator, cleaning, injection check) ----------
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
const NORMAL_STOPS = ['end_turn', 'stop_sequence'];

function deepEq(a, b) {
  if (typeof a === 'boolean' || typeof b === 'boolean') return a === b;
  if (typeof a === 'number' && typeof b === 'number') return a === b;
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((x, i) => deepEq(x, b[i]));
  if (isObj(a) && isObj(b)) {
    const ka = Object.keys(a), kb = Object.keys(b);
    return ka.length === kb.length && ka.every((k) => Object.prototype.hasOwnProperty.call(b, k) && deepEq(a[k], b[k]));
  }
  return a === b;
}

// python re.search semantics for the patterns we support: a final $ also matches before one trailing newline
function pyRegex(p) {
  const src = /(^|[^\\])\$$/.test(p) ? p.slice(0, -1) + '(?=\\n?$)' : p;
  return new RegExp(src);
}

function isDate(s) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return false;
  const y = +m[1], mo = +m[2], d = +m[3];
  if (y < 1 || mo < 1 || mo > 12 || d < 1) return false;
  const dim = [31, (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return d <= dim[mo - 1];
}

function isType(v, t) {
  switch (t) {
    case 'null': return v === null;
    case 'array': return Array.isArray(v);
    case 'object': return isObj(v);
    case 'string': return typeof v === 'string';
    case 'boolean': return typeof v === 'boolean';
    case 'number': return typeof v === 'number' && Number.isFinite(v);
    case 'integer': return typeof v === 'number' && Number.isInteger(v);
    default: return false;
  }
}

function validate(s, v, path, errs) {
  errs = errs || [];
  const label = path || 'answer';
  if (s.type !== undefined) {
    const ts = Array.isArray(s.type) ? s.type : [s.type];
    if (!ts.some((t) => isType(v, t))) { errs.push(`${label}: must be ${ts.join(' or ')}`); return errs; }
  }
  if (s.enum !== undefined && !s.enum.some((e) => deepEq(e, v)))
    errs.push(`${label}: must be one of ${s.enum.map((x) => JSON.stringify(x)).join(', ')}`);
  if (typeof v === 'number') {
    if (s.minimum !== undefined && v < s.minimum) errs.push(`${label}: must be at least ${s.minimum}`);
    if (s.maximum !== undefined && v > s.maximum) errs.push(`${label}: must be at most ${s.maximum}`);
  }
  if (typeof v === 'string') {
    const n = [...v].length;
    if (s.minLength !== undefined && n < s.minLength) errs.push(`${label}: at least ${s.minLength} characters`);
    if (s.maxLength !== undefined && n > s.maxLength) errs.push(`${label}: at most ${s.maxLength} characters`);
    if (s.pattern !== undefined && !pyRegex(s.pattern).test(v)) errs.push(`${label}: does not match the pattern ${s.pattern}`);
    if (s.format === 'date' && !isDate(v)) errs.push(`${label}: must be a real date written YYYY-MM-DD`);
  }
  if (Array.isArray(v)) {
    if (s.minItems !== undefined && v.length < s.minItems) errs.push(`${label}: at least ${s.minItems} items`);
    if (s.maxItems !== undefined && v.length > s.maxItems) errs.push(`${label}: at most ${s.maxItems} items`);
    if (s.items) v.forEach((x, i) => validate(s.items, x, `${label}[${i}]`, errs));
  }
  if (isObj(v)) {
    const props = s.properties || {};
    for (const r of s.required || []) if (!has(v, r)) errs.push(`${path ? path + '.' : ''}${r}: missing (required)`);
    for (const k of Object.keys(v)) {
      const p = path ? `${path}.${k}` : k;
      if (has(props, k)) validate(props[k], v[k], p, errs);
      else if (s.additionalProperties === false) errs.push(`${p}: field not allowed`);
    }
  }
  return errs;
}

const KNOWN = new Set(['$schema', '$id', '$comment', 'title', 'description', 'default', 'examples', 'type', 'properties',
  'required', 'additionalProperties', 'enum', 'minimum', 'maximum', 'minLength', 'maxLength', 'pattern', 'format',
  'items', 'minItems', 'maxItems']);
const TYPES = new Set(['object', 'array', 'string', 'number', 'integer', 'boolean', 'null']);

function schemaProblems(s, p, top) {
  p = p || 'schema';
  const out = [];
  if (!isObj(s)) return [`${p}: not an object`];
  for (const k of Object.keys(s)) if (!KNOWN.has(k)) out.push(`${p}: keyword ${k} not supported`);
  if (s.type !== undefined) {
    const ts = Array.isArray(s.type) ? s.type : [s.type];
    for (const t of ts) if (!TYPES.has(t)) out.push(`${p}: unknown type ${JSON.stringify(t)}`);
  }
  if (top && s.type !== 'object') out.push(`${p}: the top level must be type object`);
  if (s.properties !== undefined) {
    if (!isObj(s.properties)) out.push(`${p}: properties must be an object`);
    else for (const [k, v] of Object.entries(s.properties)) out.push(...schemaProblems(v, `${p}.${k}`, false));
  }
  if (s.items !== undefined) out.push(...schemaProblems(s.items, `${p}[]`, false));
  if (s.required !== undefined && !(Array.isArray(s.required) && s.required.every((x) => typeof x === 'string')))
    out.push(`${p}: required must be a list of names`);
  if (s.additionalProperties !== undefined && typeof s.additionalProperties !== 'boolean')
    out.push(`${p}: additionalProperties must be true or false`);
  if (s.enum !== undefined && !Array.isArray(s.enum)) out.push(`${p}: enum must be a list`);
  if (s.pattern !== undefined) { try { pyRegex(String(s.pattern)); } catch (e) { out.push(`${p}: pattern does not compile`); } }
  if (s.format !== undefined && s.format !== 'date') out.push(`${p}: format ${s.format} not supported`);
  for (const k of ['minimum', 'maximum', 'minLength', 'maxLength', 'minItems', 'maxItems'])
    if (s[k] !== undefined && typeof s[k] !== 'number') out.push(`${p}: ${k} must be a number`);
  return out;
}

// the only repair: text from the first { to the last }, only when the text does not parse as it is (strict JSON)
function cleanParse(text) {
  if (text === null || text === undefined) return { ok: false, why: 'empty answer' };
  const t = String(text).trim();
  if (!t) return { ok: false, why: 'empty answer' };
  try { return { ok: true, value: JSON.parse(t), cleaned: false }; } catch (e) { /* try cleaning */ }
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b <= a) return { ok: false, why: 'no JSON object in the answer' };
  try { return { ok: true, value: JSON.parse(t.slice(a, b + 1)), cleaned: true }; }
  catch (e) { return { ok: false, why: 'the answer is not valid JSON' }; }
}

